-- transfer(1,2) and transfer(2,1) run together and deadlock. Fix the lock order.

class Queue {
  constructor(){ this.jobs = [ {id:1,status:'queued'}, {id:2,status:'queued'}, {id:3,status:'queued'} ]; }
  claim(){
    const job = this.jobs.find(j => j.status === 'queued');
    return job ? job.id : null;
  }
}

